            return subtotal.multiply(new BigDecimal("0.02")).setScale(2, RoundingMode.HALF_EVEN);
        }

        @Override
        public boolean temBrinde(BigDecimal subtotal) { return false; }
    },

    OURO {
        @Override
        public boolean isFreteGratis() { return true; }

